cy.get('[aria-label="Zoomer"], button.ol-zoom-in', {
  timeout: 10000
}).first().should('be.visible');
cy.get('[aria-label="Dézoomer"], button.ol-zoom-out', {
  timeout: 10000
}).first().should('be.visible');

cy.intercept({
  url: /data\.geopf\.fr.*geocodage|completion/
}).as('geocode');
cy.get('input[type="search"], input[placeholder*="echerch"], input[placeholder*="earch"], input[aria-label*="echerch"]', {
  timeout: 10000
}).first().clear().type('Paris');
// Des suggestions ou résultats apparaissent
cy.get('[role="listbox"], [role="option"], [class*="suggestion"], [class*="result"], [class*="autocomplete"] li', {
  timeout: 10000
}).should('have.length.at.least', 1);

// Chercher un bouton/menu d'outils (mesure, dessin, etc.)
cy.get('[aria-label*="outil"], [aria-label*="mesur"], [aria-label*="tool"], button[class*="tool"], [class*="toolbox"]', {
  timeout: 10000
}).should('have.length.at.least', 0); // L'outil peut ne pas être directement visible

// Test que l'endpoint itinéraire est joignable
cy.request({
  url: 'https://data.geopf.fr/navigation/itineraire?resource=bdtopo-osrm&start=2.3522,48.8566&end=2.2945,48.8584&profile=car&optimization=fastest',
  timeout: 15000,
  failOnStatusCode: false
}).then(response => {
  // L'API doit répondre (200 ou 400 si params invalides, mais pas 5xx)
  expect(response.status).to.be.lessThan(500);
});

cy.intercept({
